using System.Collections.Immutable;

namespace SharpProof.Analyzer;

internal static class AnalyzerGeneratedCodePolicy
{
    private static readonly ImmutableArray<string> GeneratedPathSuffixes = [
        ".g.cs",
        ".g.i.cs",
        ".generated.cs",
        ".designer.cs"];
    private static readonly ImmutableArray<string> GeneratedHeaderTokens = [
        "<auto-generated",
        "<autogenerated"];
    private static readonly ConditionalWeakTable<
        Compilation,
        ConcurrentDictionary<SyntaxTree, GeneratedCodeResult>> GeneratedCodeCache = new();

    internal static bool IsGenerated(
        ISymbol symbol,
        SyntaxTree tree,
        Compilation compilation,
        CancellationToken cancellationToken)
    {
        compilation = RepositoryParameterGuard.NotNull(compilation, nameof(compilation));
        tree = RepositoryParameterGuard.NotNull(tree, nameof(tree));
        symbol = RepositoryParameterGuard.NotNull(symbol, nameof(symbol));

        var generated = GetGeneratedCode(
            tree,
            compilation,
            cancellationToken);
        return generated.IsGenerated ||
            generated.Kind is not (
                GeneratedKind.MarkedGenerated or
                GeneratedKind.NotGenerated) &&
            HasGeneratedCodeAttribute(symbol, compilation);
    }

    internal static bool IsGenerated(
        SyntaxTree tree,
        Compilation compilation,
        CancellationToken cancellationToken)
    {
        compilation = RepositoryParameterGuard.NotNull(compilation, nameof(compilation));
        tree = RepositoryParameterGuard.NotNull(tree, nameof(tree));
        return GetGeneratedCode(tree, compilation, cancellationToken).IsGenerated;
    }

    private static GeneratedCodeResult GetGeneratedCode(
        SyntaxTree tree,
        Compilation compilation,
        CancellationToken cancellationToken)
    {
        compilation = RepositoryParameterGuard.NotNull(compilation, nameof(compilation));
        cancellationToken.ThrowIfCancellationRequested();
        var cache = GeneratedCodeCache.GetValue(
            compilation,
            static _ => new(ReferenceComparer<SyntaxTree>.Instance));
        if (cache.TryGetValue(tree, out var cached))
        {
            return cached;
        }

        var kind = compilation.Options.SyntaxTreeOptionsProvider?
            .IsGenerated(tree, cancellationToken) ?? GeneratedKind.Unknown;
        var result = new GeneratedCodeResult(
            kind,
            kind switch
            {
                GeneratedKind.MarkedGenerated => true,
                GeneratedKind.NotGenerated => false,
                _ => HasGeneratedPath(tree.FilePath) ||
                    HasGeneratedHeader(tree, cancellationToken)
            });
        cache.TryAdd(tree, result);
        return result;
    }

    private sealed class GeneratedCodeResult(
        GeneratedKind kind,
        bool isGenerated)
    {
        internal GeneratedKind Kind { get; } = kind;
        internal bool IsGenerated { get; } = isGenerated;
    }

    private static bool HasGeneratedPath(string path)
    {
        path = RepositoryParameterGuard.NotNull(path, nameof(path));
        return GeneratedPathSuffixes.Any(suffix =>
            suffix is null ? throw new System.ArgumentNullException(nameof(suffix)) : (path.EndsWith(suffix, StringComparison.OrdinalIgnoreCase)));
    }

    private static bool HasGeneratedHeader(
        SyntaxTree tree,
        CancellationToken cancellationToken)
    {
        // Match Roslyn's heuristic by scanning every leading comment for a
        // generated marker instead of requiring an exact first comment.
        tree = RepositoryParameterGuard.NotNull(tree, nameof(tree));
        foreach (var trivia in tree.GetRoot(cancellationToken)
                     .GetLeadingTrivia())
        {
            if (!trivia.IsKind(SyntaxKind.SingleLineCommentTrivia) &&
                !trivia.IsKind(SyntaxKind.MultiLineCommentTrivia))
            {
                continue;
            }

            var comment = trivia.ToString();
            if (GeneratedHeaderTokens.Any(token => token is null ? throw new System.ArgumentNullException(nameof(token)) : (comment.IndexOf(
                    token,
                    StringComparison.OrdinalIgnoreCase) >= 0)))
            {
                return true;
            }
        }

        return false;
    }

    private static bool HasGeneratedCodeAttribute(
        ISymbol symbol,
        Compilation compilation)
    {
        compilation = RepositoryParameterGuard.NotNull(compilation, nameof(compilation));
        symbol = RepositoryParameterGuard.NotNull(symbol, nameof(symbol));
        var generatedCode = compilation.GetTypeByMetadataName(
            FrameworkTypeMetadataNames.GeneratedCodeAttribute);
        if (generatedCode == null)
        {
            return false;
        }

        var scopes = new List<ISymbol> { symbol };
        if (symbol is IMethodSymbol { AssociatedSymbol: { } associated })
        {
            scopes.Add(associated);
        }
        for (var type = symbol.ContainingType;
             type != null;
             type = type.ContainingType)
        {
            scopes.Add(type);
        }

        foreach (var scope in scopes)
        {
            if (scope.GetAttributes().Any(attribute =>
                    attribute is null ? throw new System.ArgumentNullException(nameof(attribute)) : (SymbolEqualityComparer.Default.Equals(
                        attribute.AttributeClass?.OriginalDefinition,
                        generatedCode.OriginalDefinition))))
            {
                return true;
            }
        }

        return false;
    }
}
